import sys

def is_nice_string(s):
    # Check for at least 3 vowels (a, e, i, o, u)
    vowels = 'aeiou'
    vowel_count = sum(1 for char in s if char in vowels)
    if vowel_count < 3:
        return False

    # Check for at least one double letter (e.g., "aa", "bb")
    has_double = False
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            has_double = True
            break
    if not has_double:
        return False

    # Check for disallowed substrings: ab, cd, pq, xy
    disallowed = ['ab', 'cd', 'pq', 'xy']
    for substring in disallowed:
        if substring in s:
            return False

    return True

# Read input from standard input and count nice strings
nice_count = 0
for line in sys.stdin:
    line = line.strip()
    if line:  # Skip empty lines
        if is_nice_string(line):
            nice_count += 1

print(nice_count)

def solve(lines):
    # Initialize 1000x1000 grid with 0 (OFF)
    grid = [[0 for _ in range(1000)] for _ in range(1000)]

    for line in lines:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        # Format: turn on/off/toggle x1,y1 through x2,y2
        command = parts[1]

        start_coord = parts[2]
        end_coord = parts[4]

        x1, y1 = map(int, start_coord.split(','))
        x2, y2 = map(int, end_coord.split(','))

        # Ensure x1 <= x2 and y1 <= y2
        if x1 > x2:
            x1, x2 = x2, x1
        if y1 > y2:
            y1, y2 = y2, y1

        for r in range(y1, y2 + 1):
            for c in range(x1, x2 + 1):
                if command == 'on':
                    grid[r][c] = 1
                elif command == 'off':
                    grid[r][c] = 0
                elif command == 'toggle':
                    grid[r][c] = 1 - grid[r][c]

    # Count lit lights (1s)
    lit_count = sum(sum(row) for row in grid)
    print(lit_count)

if __name__ == "__main__":
    lines = []
    try:
        while True:
            line = input()
            lines.append(line)
    except EOFError:
        pass

    solve(lines)

