                        'dest': dest,
                        'op': op,
                        'src1': tokens[0],
                        'src2': tokens[2]
                    })
                else:
                    # LSHIFT or RSHIFT
                    instructions.append({
                        'dest': dest,
                        'op': op,
                        'src': tokens[0],
