def count_combinations(containers, target):
    """
    Count the number of combinations of containers that sum exactly to target.
    Each container can be used at most once.
    """
    n = len(containers)
    memo = {}

    def backtrack(index, current_sum):
        if current_sum == target:
            return 1
        if current_sum > target or index >= n:
            return 0
        if (index, current_sum) in memo:
            return memo[(index, current_sum)]

        # Option 1: Skip current container
        count = backtrack(index + 1, current_sum)

        # Option 2: Include current container if it doesn't exceed target
        if current_sum + containers[index] <= target:
            count += backtrack(index + 1, current_sum + containers[index])

        memo[(index, current_sum)] = count
        return count

    return backtrack(0, 0)


