def solve(grid):
    # grid is 100x100
    # Pad to 102x102
    rows = 102
    cols = 102
    padded_grid = [[0] * cols for _ in range(rows)]

    for r in range(100):
        for c in range(100):
            if grid[r][c] == 1:
                padded_grid[r+1][c+1] = 1

    # Simulation
    for _ in range(100):
        new_grid = [[0] * cols for _ in range(rows)]
        for r in range(1, 101):
            for c in range(1, 101):
                neighbors = 0
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        neighbors += padded_grid[nr][nc]

                if padded_grid[r][c] == 1:
                    if neighbors == 2 or neighbors == 3:
                        new_grid[r][c] = 1
                else:
                    if neighbors == 3:
                        new_grid[r][c] = 1
        padded_grid = new_grid

    # Count lights in the 100x100 area
    count = 0
    for r in range(1, 101):
        for c in range(1, 101):
            count += padded_grid[r][c]
    return count

