def run_program(instructions, initial_a=0):
    # Parse instructions
    parsed = []
    for line in instructions:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        if op in ('hlf', 'tpl', 'inc'):
            reg = parts[1].replace(',', '')
            parsed.append((op, reg))
        elif op == 'jmp':
            offset_str = parts[1].replace(',', '')
            parsed.append((op, int(offset_str)))
        elif op in ('jie', 'jio'):
            reg = parts[1].replace(',', '')
            offset_str = parts[2].replace(',', '')
            parsed.append((op, reg, int(offset_str)))

    regs = {'a': initial_a, 'b': 0}
    pc = 0
    n = len(parsed)

    while pc < n:
        op = parsed[pc][0]
        if op == 'hlf':
            regs[parsed[pc][1]] //= 2
            pc += 1
        elif op == 'tpl':
            regs[parsed[pc][1]] *= 3
            pc += 1
        elif op == 'inc':
            regs[parsed[pc][1]] += 1
            pc += 1
        elif op == 'jmp':
            pc += parsed[pc][1]
        elif op == 'jie':
            if regs[parsed[pc][1]] % 2 == 0:
                pc += parsed[pc][1]
            else:
                pc += 1
        elif op == 'jio':
            if regs[parsed[pc][1]] == 1:
                pc += parsed[pc][1]
            else:
                pc += 1
        else:
            # Unknown instruction, break
            break

    return regs['b']

