def get_bathroom_code(instructions):
    # Keypad layout
    # 1 2 3
    # 4 5 6
    # 7 8 9
    # Start at 5

    # Mapping digits to (row, col)
    digit_map = {
        '1': (0, 0), '2': (0, 1), '3': (0, 2),
        '4': (1, 0), '5': (1, 1), '6': (1, 2),
        '7': (2, 0), '8': (2, 1), '9': (2, 2)
    }
    # Reverse mapping for coordinate to digit
    coord_map = {v: k for k, v in digit_map.items()}

    current_pos = '5'
    code = []

    for instruction in instructions:
        # Get current coordinates
        r, c = digit_map[current_pos]

        for move in instruction:
            # Determine new coordinates based on move
            if move == 'U':
                r -= 1
            elif move == 'D':
                r += 1
            elif move == 'L':
                c -= 1
            elif move == 'R':
                c += 1

            # Check bounds (0-2 for both row and col)
            if 0 <= r < 3 and 0 <= c < 3:
                current_pos = coord_map[(r, c)]
            # If out of bounds, ignore the move (stay on current_pos)

        code.append(current_pos)

    return "".join(code)

