def solve():
    # Screen dimensions
    WIDTH = 50
    HEIGHT = 6

    # Initialize screen (0 = off, 1 = on)
    screen = [[0 for _ in range(WIDTH)] for _ in range(HEIGHT)]

    # Read input lines
    lines = []
    try:
        while True:
            line = input()
            if line.strip():
                lines.append(line)
    except EOFError:
        pass

    # Process instructions
    for line in lines:
        parts = line.strip().split()
        if not parts:
            continue

        command = parts[0]

        if command == 'rect':
            # rect AxB
            dim = parts[1]
            a, b = map(int, dim.split('x'))
            for r in range(b):
                for c in range(a):
                    screen[r][c] = 1

        elif command == 'rotate':
            if parts[1] == 'row':
                # rotate row y=A by B
                y = int(parts[2].split('=')[1])
                b = int(parts[4])

                shift = b % WIDTH
                if shift != 0:
                    row = screen[y]
                    row = row[-shift:] + row[:-shift]
                    screen[y] = row

            elif parts[1] == 'column':
                # rotate column x=A by B
                x = int(parts[2].split('=')[1])
                b = int(parts[4])

                col = [screen[r][x] for r in range(HEIGHT)]

                shift = b % HEIGHT
                if shift != 0:
                    col = col[-shift:] + col[:-shift]
                    for r in range(HEIGHT):
                        screen[r][x] = col[r]

    # Part 1: Count lit pixels
    lit_pixels = sum(sum(row) for row in screen)
    print(lit_pixels)

    # Part 2: Display the message
    for row in screen:
        print("".join(map(str, row)))

