def solve_part1(text):
    """Part 1: Simple marker decompression"""
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '(':
            # Find the closing parenthesis
            j = i + 1
            while j < n and text[j] != ')':
                j += 1

            if j < n:
                # Parse the marker (nxm)
                marker_str = text[i+1:j]
                parts = marker_str.split('x')
                if len(parts) == 2:
                    repeat_count = int(parts[0])
                    repeat_times = int(parts[1])

                    # Move past the marker
                    i = j + 1

                    # Read and repeat the data
                    for _ in range(repeat_times):
                        for _ in range(repeat_count):
                            if i < n:
                                result.append(text[i])
                                i += 1
                else:
                    # Not a valid marker, treat as normal data
                    result.append(text[i])
                    i += 1
            else:
                result.append(text[i])
                i += 1
        else:
            result.append(text[i])
            i += 1

    return len(result)


def solve_part2(text):
    """Part 2: Recursive marker decompression"""
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '(':
            # Find the closing parenthesis
            j = i + 1
            while j < n and text[j] != ')':
