def solve(spiral_number):
    if spiral_number == 1:
        return 0

    # Find the layer n
    n = 0
    while (2 * n + 1) ** 2 < spiral_number:
        n += 1

    s = 2 * n + 1
    start = (s - 2) ** 2 + 1

    offset = spiral_number - start

    if offset < s:
        # Top segment
        x = offset
        y = n
    elif offset < 2 * s:
        # Right segment
        x = s - 1
        y = n - (offset - s)
    elif offset < 3 * s:
        # Bottom segment
        x = s - 1 - (offset - 2 * s)
        y = -(s - 1)
    else:
        # Left segment
        x = -(s - 1)
        y = -(s - 1) + (offset - 3 * s)

    return abs(x) + abs(y)

