import heapq
import re

def solve(lines):
    dependencies = {}
    in_degree = {}
    all_steps = set()

    # Regex pattern to extract step letters
    # Format: "Step X must be finished before step Y can begin."
    pattern = re.compile(r'Step\s+(\w+)\s+must\s+be\s+finished\s+before\s+step\s+(\w+)\s+can\s+begin\.')

    for line in lines:
        match = pattern.search(line)
        if match:
            u = match.group(1)
            v = match.group(2)

            # Add to dependencies (u -> v)
            if u not in dependencies:
                dependencies[u] = []
            dependencies[u].append(v)

            # Update in-degree for v
            if v not in in_degree:
                in_degree[v] = 0
            in_degree[v] += 1

            # Track all steps
            all_steps.add(u)
            all_steps.add(v)

    # Ensure all steps have an entry in in_degree
    for step in all_steps:
        if step not in in_degree:
            in_degree[step] = 0

    # Min-heap for available steps (alphabetical order)
    available = []
    for step in all_steps:
        if in_degree[step] == 0:
            heapq.heappush(available, step)

    result = []

    while available:
        current = heapq.heappop(available)
        result.append(current)

        # Process neighbors
        if current in dependencies:
            for neighbor in dependencies[current]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    heapq.heappush(available, neighbor)

    return "".join(result)

if __name__ == "__main__":
    lines = []
    try:
        while True:
            line = input()
            lines.append(line)
    except EOFError:
        pass

    if lines:
        print(solve(lines))

