class IntcodeComputer:
    def __init__(self, program):
        self.memory = program.copy()
        self.ip = 0
        self.halted = False
        self.output = []

    def run(self, input_commands=None):
        self.output = []
        self.ip = 0
        self.halted = False
        input_commands = input_commands or []
        input_idx = 0

        while not self.halted and self.ip < len(self.memory):
            opcode = self.memory[self.ip]
            if opcode == 1:
                a, b, c = self.memory[self.ip + 1], self.memory[self.ip + 2], self.memory[self.ip + 3]
                self.memory[c] = self.memory[a] + self.memory[b]
                self.ip += 4
            elif opcode == 2:
                a, b, c = self.memory[self.ip + 1], self.memory[self.ip + 2], self.memory[self.ip + 3]
                self.memory[c] = self.memory[a] * self.memory[b]
                self.ip += 4
            elif opcode == 3:
                if input_idx < len(input_commands):
                    self.memory[self.memory[self.ip + 1]] = ord(input_commands[input_idx])
                    input_idx += 1
                else:
                    self.memory[self.memory[self.ip + 1]] = 0
                self.ip += 2
            elif opcode == 4:
                self.output.append(self.memory[self.memory[self.ip + 1]])
                self.ip += 2
            elif opcode == 99:
                self.halted = True
                self.ip += 1
            else:
                self.ip += 1

    def get_output(self):
        return ''.join(chr(b) for b in self.output)

    def reset(self):
        self.memory = self.memory.copy()
        self.ip = 0
        self.halted = False
        self.output = []

