import re

def evaluate_flat(expression):
    # Tokenize the expression into numbers and operators
    tokens = re.findall(r'\d+|[+\*]', expression)

    if not tokens:
        return 0

    current_value = int(tokens[0])

    # Iterate through operators and next numbers
    # Since we removed spaces, tokens are strictly [num, op, num, op, num...]
    for i in range(1, len(tokens), 2):
        operator = tokens[i]
        next_value = int(tokens[i+1])

        if operator == '+':
            current_value += next_value
        elif operator == '*':
            current_value *= next_value

    return current_value

def evaluate_expression(expression):
    # Remove spaces to simplify processing
    expression = expression.replace(" ", "")

    # Base case: if no parentheses, evaluate left-to-right
    if '(' not in expression:
        return evaluate_flat(expression)

    # Find the first opening parenthesis
    first_open = expression.find('(')

    # Find the matching closing parenthesis
    depth = 0
    close_idx = -1
    for i, char in enumerate(expression):
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
            if depth == 0:
                close_idx = i
                break

    if close_idx == -1:
        # Should not happen in valid input
        return 0

    # Extract inner expression
    inner_expr = expression[first_open + 1 : close_idx]

    # Recursively evaluate the inner expression
    evaluated_inner = evaluate_expression(inner_expr)

    # Replace the parenthesized part with the evaluated result
    new_expression = expression[:first_open] + str(evaluated_inner) + expression[close_idx + 1:]

    # Recursively evaluate the new expression (handles outer parentheses)
    return evaluate_expression(new_expression)

