from collections import deque

def solve(grid_lines):
    start_pos = None
    end_pos = None

    # Identify start and end positions
    for r, line in enumerate(grid_lines):
        for c, char in enumerate(line):
            if char == 'S':
                start_pos = (r, c)
            elif char == 'E':
                end_pos = (r, c)

    # Helper to calculate elevation
    def get_elevation(char):
        if char == 'S':
            return 0
        elif char == 'E':
            return 25
        else:
            return ord(char) - ord('a')

    # BFS initialization
    # Queue stores (row, col, distance)
    queue = deque([(start_pos[0], start_pos[1], 0)])
    visited = set()
    visited.add(start_pos)

    # Directions: Up, Down, Left, Right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()

        # Check if reached destination
        if (r, c) == end_pos:
            return dist

        current_elev = get_elevation(grid_lines[r][c])

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check boundaries
            if 0 <= nr < len(grid_lines) and 0 <= nc < len(grid_lines[0]):
                if (nr, nc) not in visited:
                    neighbor_elev = get_elevation(grid_lines[nr][nc])

                    # Check elevation constraint: destination <= current + 1
                    if neighbor_elev <= current_elev + 1:
                        visited.add((nr, nc))
                        queue.append((nr, nc, dist + 1))

    return -1

