def compare(left, right):
    # If both are integers
    if isinstance(left, int) and isinstance(right, int):
        return left < right

    # If one is int, convert to list
    if isinstance(left, int):
        left = [left]
    if isinstance(right, int):
        right = [right]

    # Now both are lists
