import sys

def solve(grid):
    # Find start position
    start_pos = None
    rows = len(grid)
    cols = len(grid[0])

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
                break
        if start_pos:
            break

    if not start_pos:
        return 0

    # Current reachable positions at step k
    current_positions = {start_pos}

    # Directions: North, South, East, West
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for step in range(64):
        next_positions = set()
        for r, c in current_positions:
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                # Check bounds
                if 0 <= nr < rows and 0 <= nc < cols:
                    # Check if valid tile (not rock)
                    if grid[nr][nc] != '#':
                        next_positions.add((nr, nc))
        current_positions = next_positions
        if not current_positions:
