import sys
from collections import deque

def bfs(grid, start, end):
    rows = len(grid)
    cols = len(grid[0])

    # Check if start or end is blocked
    if grid[start[1]][start[0]] == 1 or grid[end[1]][end[0]] == 1:
        return False

    queue = deque([start])
    visited = {start}

    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            return True

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy

            if 0 <= nx < cols and 0 <= ny < rows:
                if grid[ny][nx] == 0 and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
    return False

def solve(byte_positions):
    # Initialize grid 71x71
    grid = [[0] * 71 for _ in range(71)]

    for x, y in byte_positions:
        # Mark byte position as corrupted
        grid[y][x] = 1

        # Check if exit is reachable
        if not bfs(grid, (0, 0), (70, 70)):
            return f"{x},{y}"

    return None

