def can_form(design, patterns):
    n = len(design)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(n):
        if dp[i]:
            for pattern in patterns:
                if design.startswith(pattern, i):
                    dp[i + len(pattern)] = True

    return dp[n]

