def can_fit(grid, counts, shapes):
    # grid: 2D list of booleans
    # counts: list of ints
    # shapes: list of lists of orientations (each orientation is list of (r,c))

    # Find first empty cell
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if not grid[r][c]:
                # Try to place a shape covering (r, c)
                for i in range(len(shapes)):
                    if counts[i] > 0:
                        for orientation in shapes[i]:
                            # Try to place orientation such that one of its cells is at (r, c)
                            for dr, dc in orientation:
                                # Calculate top-left (gr, gc)
                                gr, gc = r - dr, c - dc

                                # Check bounds and overlap
                                valid = True
                                cells_to_mark = []
                                for rr, cc in orientation:
                                    nr, nc = gr + rr, gc + cc
                                    if nr < 0 or nr >= len(grid) or nc < 0 or nc >= len(grid[0]):
                                        valid = False
                                        break
                                    if grid[nr][nc]:
                                        valid = False
                                        break
                                    cells_to_mark.append((nr, nc))

                                if valid:
                                    # Place
                                    for nr, nc in cells_to_mark:
                                        grid[nr][nc] = True
                                    counts[i] -= 1
                                    if can_fit(grid, counts, shapes):
                                        return True
                                    # Backtrack
                                    counts[i] += 1
                                    for nr, nc in cells_to_mark:
                                        grid[nr][nc] = False
                # If we reach here, no shape could cover (r, c)
                return False
    # If no empty cell found, check if all counts are 0
    return all(c == 0 for c in counts)
